import pandas as pd

def get_scores(rolls):
    # rolls is a list/array of 6 integers
    scores = []

    # 1. High and Often
    max_val = max(rolls)
    count_max = 0
    for r in rolls:
        if r == max_val:
            count_max += 1
    scores.append(max_val * count_max)

    # 2. Summation
    scores.append(sum(rolls))

    # 3. Highs and Lows
    min_val = min(rolls)
    scores.append(max_val * min_val * (max_val - min_val))

    # 4. Only two numbers
    if len(set(rolls)) <= 2:
        scores.append(30)
    else:
        scores.append(0)

    # 5. All the numbers
    if set(rolls) == {1, 2, 3, 4, 5, 6}:
        scores.append(40)
    else:
        scores.append(0)

    # 6. Ordered subset of four
    found = False
    for i in range(3):
        subset = rolls[i:i+4]
        # increasing
        if subset[1] == subset[0]+1 and subset[2] == subset[1]+1 and subset[3] == subset[2]+1:
            found = True
            break
        # decreasing
        if subset[1] == subset[0]-1 and subset[2] == subset[1]-1 and subset[3] == subset[2]-1:
            found = True
            break
    if found:
        scores.append(50)
    else:
        scores.append(0)

    return scores

def get_game_score(turn1_rolls, turn2_rolls):
    s1 = get_scores(turn1_rolls) if turn1_rolls is not None else [0]*6
    s2 = get_scores(turn2_rolls) if turn2_rolls is not None else [0]*6

    max_score = 0
    for i in range(6):
        for j in range(6):
            if i != j:
                max_score = max(max_score, s1[i] + s2[j])
    return max_score

# Load data
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=None, skiprows=9)
df = df.iloc[:, 2:10].dropna(subset=[2])
df.columns = ['Turn', 'Game', 'R1', 'R2', 'R3', 'R4', 'R5', 'R6']

# Group by Game
game_turns = {}
for _, row in df.iterrows():
    g = int(row['Game'])
    rolls = [int(row[f'R{i}']) for i in range(1, 7)]
    if g not in game_turns:
        game_turns[g] = []
    game_turns[g].append(rolls)

# Calculate scores for all 3000 games
game_scores = {}
for g in range(1, 3001):
    turns = game_turns.get(g, [])
    if len(turns) == 2:
        game_scores[g] = get_game_score(turns[0], turns[1])
    elif len(turns) == 1:
        # If only one turn, the other turn is considered to have 0 in all categories
        game_scores[g] = get_game_score(turns[0], None)
    else:
        game_scores[g] = 0

# Matches
p1_wins = 0
p2_wins = 0
for m in range(1, 1501):
    g1 = 2*m - 1
    g2 = 2*m
    s1 = game_scores[g1]
    s2 = game_scores[g2]
    if s1 > s2:
        p1_wins += 1
    elif s2 > s1:
        p2_wins += 1

print(p1_wins - p2_wins)

